"""Build an offline, illustrated B-version test guide from exported Unity configuration."""
from pathlib import Path
import json
import shutil

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'11_UnityReskin/Design/SimpleTestGuide20260917'
DATA=json.loads((OUT/'rules.json').read_text(encoding='utf-8-sig'))
DATA['countries']={}
names=dict(zip('US GB CA DE FR AU BR MY TR MX ZA EG RU IN PH TH PK BD NG JP AR KZ CO KR VN ID'.split(), '美国 英国 加拿大 德国 法国 澳大利亚 巴西 马来西亚 土耳其 墨西哥 南非 埃及 俄罗斯 印度 菲律宾 泰国 巴基斯坦 孟加拉国 尼日利亚 日本 阿根廷 哈萨克斯坦 哥伦比亚 韩国 越南 印度尼西亚'.split()))
for code in DATA['rules']['supportedCountries']:
    loc=json.loads((ROOT/f'11_UnityReskin/Assets/Resources/Localization/Text/{code}.json').read_text(encoding='utf-8-sig'))
    DATA['countries'][code]={'name':names.get(code,code),'currency':loc['currency']}
vpath=OUT/'validation.json'
DATA['validation']=json.loads(vpath.read_text(encoding='utf-8-sig')) if vpath.exists() else {}
for source,name in [('GuideTextFix20260917/US_step4_941.png','guide.png'),('VisualAudit20260917/Startup/After_startup_1_zero.png','loading.png')]:
    path=OUT.parent/source
    if path.exists():shutil.copy2(path,OUT/name)

